// This Java code maps to UML class diagram elements

// Abstract class (name in italics in UML)
public abstract class Vehicle {
    private String licensePlate;  // - licensePlate: String
    protected VehicleType type;   // # type: VehicleType

    public abstract double getSize();  // + getSize(): double (italic)
}

// Concrete subclass (solid arrow pointing to Vehicle)
public class Car extends Vehicle {
    private int seatCount;  // - seatCount: int

    @Override
    public double getSize() {  // + getSize(): double
        return 1.0;  // Standard car spot size
    }
}

// Composition (filled diamond from ParkingLot to ParkingFloor)
public class ParkingLot {
    private List<ParkingFloor> floors;  // - floors: List<ParkingFloor> (1..*)

    public void addFloor(ParkingFloor floor) {
        this.floors.add(floor);
    }
}

