// Main container — owns floors
public class ParkingLot {
    private String name;
    private List<ParkingFloor> floors;  // Composition: filled diamond

    public Optional<ParkingSpot> findAvailableSpot(VehicleType type) {
        return floors.stream()
            .flatMap(floor -> floor.findSpot(type).stream())
            .findFirst();
    }
}

// One floor in the lot
public class ParkingFloor {
    private int floorNumber;
    private List<ParkingSpot> spots;  // Composition: spots die with floor
}

// Individual spot
public class ParkingSpot {
    private String spotId;
    private VehicleType type;  // COMPACT, LARGE, MOTORCYCLE
    private boolean isOccupied;
    private Vehicle currentVehicle;  // Association: temporary relationship
}

// Abstract vehicle hierarchy
public abstract class Vehicle {
    private String licensePlate;
    public abstract VehicleType getType();
}

public class Car extends Vehicle {  // Solid arrow to Vehicle
    @Override
    public VehicleType getType() { return VehicleType.COMPACT; }
}

public class Motorcycle extends Vehicle {
    @Override
    public VehicleType getType() { return VehicleType.MOTORCYCLE; }
}

// Links vehicle to spot for billing
public class ParkingTicket {
    private String ticketId;
    private Vehicle vehicle;  // Association
    private ParkingSpot spot;  // Association
    private LocalDateTime entryTime;

    public double calculateFee() {
        var duration = Duration.between(entryTime, LocalDateTime.now());
        return new FeeCalculator().calculate(vehicle.getType(), duration);
    }
}

// Interface in UML: box with <<interface>> stereotype
public interface PaymentProcessor {
    PaymentResult processPayment(double amount);  // Method signature only
    void refund(String transactionId);
}

// Dashed arrow with hollow head points from CreditCardProcessor to PaymentProcessor
public class CreditCardProcessor implements PaymentProcessor {
    private String merchantId;

    @Override
    public PaymentResult processPayment(double amount) {
        // Credit card specific logic
        return new PaymentResult(true, "TXN123");
    }

    @Override
    public void refund(String transactionId) {
        // Refund implementation
    }
}

// Another implementation, dashed arrow to same interface
public class PayPalProcessor implements PaymentProcessor {
    private String apiKey;

    @Override
    public PaymentResult processPayment(double amount) {
        // PayPal API call
        return new PaymentResult(true, "PP456");
    }

    @Override
    public void refund(String transactionId) {
        // PayPal refund logic
    }
}

// Abstract class (name in italics) with solid arrow from subclasses
public abstract class OnlinePaymentProcessor implements PaymentProcessor {
    protected boolean validateAmount(double amount) {  // Shared implementation
        return amount > 0 && amount < 100000;
    }
}
